#!/usr/bin/env node
// Builds docs/shots/catalog.json and docs/shots/catalog.md from the entries below.
//   node docs/shots/build-catalog.mjs
// Every recipe is evaluated against the shot-lab handles (projects/shot-lab/world-handles.mjs) to
// measure its real duration and lens range, so the catalog can never drift from engine/camera.js.
// Then run `node projects/shot-lab/test-camera.mjs --catalog` for the smoothness proof of all 200.
//
// Entry: S(cat, name, use, { purpose, scale, energy, cost, sets, recipe, t0?, lab?, note? })
//   purpose  beat jobs it serves (shot-design vocabulary): place object person number mechanism
//            tension reveal memory time chapter ending transition
//   scale    wide | medium | close   (for the alternation rule)
//   energy   low | mid | high        (for the alternation rule)
//   cost     T1 (<= 300 ms/frame: void or single-object set) | T2 (300-450: city, characters,
//            moving subjects) | T3 (> 450: multi-scale oners, DOF/AO, many lights). Average <= 450.
import { register } from 'node:module';
import fs from 'node:fs';
import path from 'node:path';
const here = path.dirname(new URL(import.meta.url).pathname), root = path.resolve(here, '../..');
register('data:text/javascript,' + encodeURIComponent(`export async function resolve(s, c, n) { if (s === 'kit') return n(${JSON.stringify('file://' + root + '/engine/kit.js')}, c); return n(s, c); }`));
const M = await import(root + '/engine/camera.js');
const { world } = await import(root + '/projects/shot-lab/world-handles.mjs');
const W = world();

const CATS = {
  EST: ['Establishing and scale', 'Where are we, and how big is it. Open chapters and sections; reset geography after a run of closes.'],
  REV: ['Reveal', 'Withhold, then show. The move itself delivers the information: a payoff, a twist, the answer to an open loop.'],
  FOL: ['Follow and tracking', 'The camera is locked to a moving subject (Fincher): the audience rides with intent, momentum and chase.'],
  ONE: ['Oner and bridge', 'Continuous moves that link two scenes or two scales without a cut (Cuarón/Lubezki "elastic" shots, Powers of Ten).'],
  CHR: ['Character and silhouette', 'A person as a shape against light: intimacy, isolation, the stoic operator. No CG faces, ever.'],
  OBJ: ['Object and macro', 'Evidence. One object in a void or on a surface, read by a slow, close, motivated camera.'],
  DAT: ['Data and map', 'Numbers, places and systems: maps that the camera flies to, globes, god\'s-eye patterns, diagrams.'],
  TRN: ['Transition camera', 'Moves designed to cut on: whips, push-ins into darkness, match moves, velocity hand-offs between shots.'],
  END: ['Ending', 'Let it land. Pull-outs, holds, rises and fades that close a chapter or the film and leave a question.'],
};
const list = [];
const S = (cat, name, use, o) => list.push({ cat, name, use, ...o });

// ============================================================================ ESTABLISHING / SCALE
S('EST', 'Skyline IMAX push', 'Awe and scale at the top of a chapter; the city as a character (Nolan/van Hoytema large-format wides held long).', { purpose: ['place', 'chapter'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['city', 'skyline', 'port'], lab: 'world', recipe: `M.dollyIn({ target: W.tower, dist: 300, push: 0.1, az: 25, el: 2, mm: 50, dur: 9, ease: 'gentle' })` });
S('EST', 'Crane-up establishing rise', 'The classic opener: from the street to the skyline. Context after a close.', { purpose: ['place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['city', 'street', 'compound'], lab: 'world', recipe: `M.craneReveal({ target: W.tower, dist: 120, az: 30, rise: 26, mm: 24, dur: 8 })` });
S('EST', 'Tiny figure, huge world', 'Villeneuve/Fraser scale: a lone figure low in frame under architecture; isolation, insignificance.', { purpose: ['place', 'person'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['city', 'desert', 'industrial'], lab: 'world', t0: 6, recipe: `M.lockOff({ target: M.vec.add(W.figureAt(9), [0, 9, 0]), dist: 70, az: 168, el: 9, mm: 35, dur: 7 })` });
S('EST', 'Aerial hover pan', 'A calm survey of a place; a breath between dense beats (drone hover pan).', { purpose: ['place'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['city', 'coast', 'farmland'], lab: 'world', recipe: `M.pan({ pos: [60, 70, 140], from: W.tower, to: W.office, mm: 35, dur: 8 })` });
S('EST', 'God\'s-eye slow rotate', 'Pattern and order seen from above; surveillance; a system rather than a place.', { purpose: ['place', 'mechanism'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['city grid', 'port', 'parking lot', 'farmland'], lab: 'world', recipe: `M.godRotate({ target: W.plaza, h0: 160, h1: 140, spin: 20, mm: 35, dur: 9 })` });
S('EST', 'Helix rise off the tower', 'Scale grows as the camera climbs and circles; ambition, empire.', { purpose: ['place', 'chapter'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['tower', 'monument', 'lighthouse'], lab: 'world', recipe: `M.helixRise({ target: W.tower, r0: 34, r1: 80, h0: -30, h1: 44, arc: 150, mm: 24, dur: 9 })` });
S('EST', 'Ridge-line reveal', 'Drone rises over a ridge and tilts down onto the place: arrival, discovery.', { purpose: ['place', 'reveal'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['valley', 'city from hills', 'mine', 'border'], lab: 'world', recipe: `M.droneRidgeReveal({ crest: W.ridge.crest, dir: W.ridge.dir, vista: W.plaza, back: 30, low: 8, clear: 18, ahead: 40, mm: 24, dur: 9 })` });
S('EST', 'Descend into the city', 'From sky to street level: we are entering this world now.', { purpose: ['place', 'chapter'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['city', 'campus', 'base'], lab: 'world', recipe: `M.descendFromSky({ ground: W.plaza, h0: 1200, h1: 25, heading: [0, 0, -1], lookEnd: W.tower, landAt: 0.55, mm: 28, dur: 9 })` });
S('EST', 'Low-angle wide hold', 'Monumental and stable: the building as power. Hold while VO sets up.', { purpose: ['place'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['HQ', 'courthouse', 'tower'], lab: 'world', recipe: `M.lockOff({ target: M.vec.add(W.tower, [0, 6, 0]), dist: 95, az: 20, el: -14, mm: 24, dur: 7 })` });
S('EST', 'Orbit the landmark', 'The strongest single image of a place; we circle it to understand its shape.', { purpose: ['place', 'object'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['landmark', 'factory', 'monument'], lab: 'world', recipe: `M.orbit({ target: W.tower, dist: 150, az: -40, arc: 60, el: 14, mm: 35, dur: 9 })` });
S('EST', 'Pedestal up the facade', 'Height and grandeur read floor by floor; the institution looms.', { purpose: ['place'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['tower', 'HQ', 'dam'], lab: 'world', recipe: `M.pedestal({ target: M.vec.add(W.tower, [0, -30, 0]), dist: 45, az: 10, rise: 40, mm: 35, dur: 8 })` });
S('EST', 'Tilt-up to the top', 'Looking up a structure from its foot: the scale of what we are up against.', { purpose: ['place', 'tension'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['tower', 'rocket', 'tree', 'statue'], lab: 'world', recipe: `M.tiltUp({ pos: [-30, 1.6, 2], from: M.vec.add(W.tower, [0, -34, 7]), to: W.towerTop, mm: 24, dur: 7 })` });
S('EST', 'Street-level truck', 'Lateral move along a street: we are here, at human scale, among things.', { purpose: ['place'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['street', 'market', 'corridor'], lab: 'world', recipe: `M.truck({ target: [0, 3, 20], dist: 26, az: 0, el: 2, track: 26, mm: 32, dur: 7 })` });
S('EST', 'Horizon low pass', 'Skimming low toward the city: momentum into a new chapter.', { purpose: ['place', 'chapter'], scale: 'wide', energy: 'high', cost: 'T2', sets: ['desert', 'sea', 'runway', 'city'], lab: 'world', recipe: `M.trackPath({ points: [[0, 3, 260], [0, 3.5, 170], [-5, 4.5, 90], [-10, 7, 40]], target: W.tower, mm: 28, dur: 7 })` });
S('EST', 'Flyover of the square', 'Skim, then rise over the subject and leave it below: energy and geography at once.', { purpose: ['place', 'transition'], scale: 'wide', energy: 'high', cost: 'T2', sets: ['square', 'stadium', 'crash site'], lab: 'world', recipe: `M.flyover({ target: W.plaza, dir: [0, 0, -1], h0: 6, h1: 26, reach: 70, mm: 24, dur: 8 })` });
S('EST', 'Map-to-street zoom', 'Johnny Harris style: the map becomes the place. Orientation before detail.', { purpose: ['place', 'number'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['map', 'city', 'region'], lab: 'world', recipe: `M.mapFlyTo({ from: { at: [0, 0], width: 3000 }, to: { at: [W.plaza[0], W.plaza[2]], width: 120 }, tilt: 20, mm: 35, dur: 7 })` });
S('EST', 'Planet to city', 'Where on Earth: start from orbit, fall to the city. The opening of an episode.', { purpose: ['place', 'chapter'], scale: 'wide', energy: 'mid', cost: 'T3', sets: ['globe+city', 'any location intro'], lab: 'world', recipe: `M.descendFromSky({ ground: W.plaza, center: W.planet.center, radius: W.planet.radius, h0: 380000, h1: 300, heading: [0, 0, -1], mm: 35, dur: 10 })` });
S('EST', 'Jib arc down to the plaza', 'Arrive in a space from above with grace; the set is introduced like a stage.', { purpose: ['place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['plaza', 'lobby', 'factory floor'], lab: 'world', recipe: `M.jibArc({ target: W.hero, dist: 34, az: -30, swing: 25, el0: 42, el1: 8, mm: 28, dur: 7 })` });
S('EST', 'Twin-tower gap glide', 'Gliding between two buildings: canyon of power, corporate scale.', { purpose: ['place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['financial district', 'canyon', 'ship hull'], lab: 'world', recipe: `M.flyThrough({ gap: W.gap.point, dir: W.gap.dir, before: 50, after: 45, rise: 5, mm: 24, dur: 8 })` });
S('EST', 'Silent wide lock-off', 'Deakins: tension by holding. A wide where nothing moves but the world.', { purpose: ['place', 'tension'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['any exterior', 'night street'], lab: 'world', t0: 3, recipe: `M.lockOff({ target: [-20, 2, 12], dist: 60, az: 70, el: 4, mm: 40, dur: 8, drift: 0.006 })` });
S('EST', 'Slow zoom-in survey', 'Documentary long-lens zoom: observational, the watcher\'s eye. Use sparingly.', { purpose: ['place', 'tension'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['surveillance', 'border', 'compound'], lab: 'world', recipe: `M.zoomCreep({ target: W.office, dist: 160, az: 15, el: 6, mm: 65, mm1: 100, dur: 9 })` });
S('EST', 'Parallax past foreground', 'A foreground element slides past the lens to give the wide depth and presence.', { purpose: ['place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['through trees', 'past fence', 'past pillars'], lab: 'world', recipe: `M.parallaxSlide({ target: W.tower, dist: 90, az: 30, el: 3, track: 30, mm: 40, dur: 7 })` });
S('EST', 'Spiral descent to the hero', 'Funnel the viewer onto the subject of the chapter from the sky.', { purpose: ['place', 'object'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['plaza', 'crash site', 'monument'], lab: 'world', recipe: `M.spiralDescent({ target: W.hero, h0: 90, h1: 4, r0: 70, r1: 14, arc: 220, mm: 28, dur: 10 })` });
S('EST', 'Night-to-orbit establishing', 'Where we are on the planet, at the end of the intro: the terminator line, the city a point.', { purpose: ['place', 'ending'], scale: 'wide', energy: 'low', cost: 'T3', sets: ['globe+city'], lab: 'world', recipe: `M.pullBackToPlanet({ ground: W.plaza, center: W.planet.center, radius: W.planet.radius, h0: 400, h1: 420000, heading: [0, 0, -1], spin: 15, mm: 35, dur: 10 })` });

// ============================================================================ REVEAL
S('REV', 'Half-orbit reveal', 'Circle a subject to show the side we could not see: the hidden truth, the other face.', { purpose: ['reveal', 'object'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['container', 'statue', 'vehicle'], lab: 'world', recipe: `M.halfOrbitReveal({ target: W.hero, dist: 16, mm: 35, dur: 9 })` });
S('REV', 'Pull-back reveal', 'The detail was part of something bigger: context lands as the frame widens.', { purpose: ['reveal', 'ending'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['any'], lab: 'world', recipe: `M.pullBackReveal({ target: W.object, dist: 1.6, pull: 14, rise: 16, mm: 35, dur: 8 })` });
S('REV', 'Boom-down past the occluder', 'Descend from behind an object to reveal what was waiting below.', { purpose: ['reveal'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['behind wall', 'over car roof', 'treeline'], lab: 'world', recipe: `M.craneDown({ target: W.hero, dist: 18, az: 160, el: 3, rise: 14, back: 0.25, mm: 28, dur: 7 })` });
S('REV', 'Foreground wipe reveal', 'A dark foreground crosses frame, and the subject is there when it clears.', { purpose: ['reveal', 'transition'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['pillars', 'crowd', 'shelves'], lab: 'world', recipe: `M.wipeReveal({ target: W.hero, dist: 20, az: 200, mm: 32, dur: 6 })` });
S('REV', 'Tilt-down from sky', 'Start on sky or ceiling, tilt down to the subject: the world arrives.', { purpose: ['reveal', 'place'], scale: 'wide', energy: 'low', cost: 'T2', sets: ['any exterior', 'cathedral'], lab: 'world', recipe: `M.tiltUp({ pos: [10, 2, 34], from: [-10, 40, -60], to: W.hero, mm: 28, dur: 7 })` });
S('REV', 'Ridge rise to the vista', 'The drone clears the ridge and the place is suddenly all there: release of tension.', { purpose: ['reveal', 'place'], scale: 'wide', energy: 'high', cost: 'T2', sets: ['valley', 'quarry', 'city'], lab: 'world', recipe: `M.droneRidgeReveal({ crest: W.ridge.crest, dir: W.ridge.dir, vista: W.tower, back: 18, low: 5, clear: 6, ahead: 26, mm: 20, dur: 7 })` });
S('REV', 'Dolly-zoom realisation', 'Hitchcock/Spielberg vertigo: the ground shifts under the subject. Once per episode.', { purpose: ['reveal', 'tension'], scale: 'medium', energy: 'high', cost: 'T2', sets: ['figure', 'corridor', 'object'], lab: 'world', t0: 9, recipe: `M.dollyZoom({ target: W.figureHead(9), dist: 9, az: -30, el: 0, ratio: 0.45, mm: 50, dur: 4 })` });
S('REV', 'Rack to the background', 'Focus moves from foreground to what is behind it: the real subject was there all along.', { purpose: ['reveal', 'object'], scale: 'medium', energy: 'low', cost: 'T3', sets: ['desk', 'window', 'aisle'], lab: 'world', recipe: `M.rackHold({ target: W.hero, dist: 14, az: 30, el: 4, near: 2, far: 14, at: 0.4, over: 0.25, mm: 65, dur: 6 })`, note: 'Needs post.js DOF to read (T3). Pass { fx } to M.apply.' });
S('REV', 'Push past the subject', 'We move past the figure or object into what it is looking at.', { purpose: ['reveal', 'transition'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['figure at window', 'guard', 'car'], lab: 'world', recipe: `M.pushPast({ target: W.hero, dist: 14, side: 2.6, reach: 1.2, az: 200, el: 6, mm: 32, dur: 6 })` });
S('REV', 'Window push-in', 'From the dark street into the one lit window: the private room behind the public facade.', { purpose: ['reveal', 'transition'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['office', 'apartment', 'embassy'], lab: 'world', recipe: `M.pushThrough({ through: W.window.point, normal: W.window.normal, before: 22, after: 4, target: W.window.inside, mm: 35, mm1: 28, dur: 7 })` });
S('REV', 'Reverse-angle orbit to the face', 'Start behind a subject, arc around to its front: who it is, now.', { purpose: ['reveal', 'person'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['figure', 'statue', 'vehicle'], lab: 'world', t0: 9, recipe: `M.orbit({ target: M.vec.add(W.figureAt(9), [0, 1.3, 0]), dist: 5, az: -100, arc: 150, el: 3, mm: 40, dur: 7 })` });
S('REV', 'Snap zoom on the detail', 'Eased crash zoom onto the thing that matters: a jolt of attention, on a word.', { purpose: ['reveal', 'object'], scale: 'close', energy: 'high', cost: 'T2', sets: ['any detail', 'number', 'face'], lab: 'world', recipe: `M.snapZoom({ target: W.object, dist: 6, az: 30, el: 12, mm: 28, mm1: 135, dur: 0.8 })` });
S('REV', 'Overhead to eye level', 'Map view turns into presence: we drop into the place at human height.', { purpose: ['reveal', 'place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['plaza', 'battlefield', 'crime scene'], lab: 'world', t0: 12, recipe: `M.overheadToEye({ target: W.hero, dist: 22, az: 20, h0: 40, eye: 1.7, mm: 28, dur: 8 })` });
S('REV', 'Look-at shift to the second subject', 'The frame turns from A to B as the VO links them: cause and effect, owner and owned.', { purpose: ['reveal', 'mechanism'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['two objects', 'two buildings', 'two people'], lab: 'world', recipe: `M.lookAtShift({ pos: [10, 1.7, 22], from: W.hero, to: W.office, mm: 40, dur: 5 })` });
S('REV', 'Pedestal reveal over the edge', 'Rise straight up from behind a wall or car roof: the subject appears over the edge.', { purpose: ['reveal'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['wall', 'car', 'desk'], lab: 'world', recipe: `M.pedestal({ target: M.vec.add(W.hero, [0, -1.1, 0]), dist: 12, az: 180, rise: 3.2, mm: 35, dur: 5 })` });
S('REV', 'Arc-push hero landing', 'A short arc that settles on the hero angle: the definitive image of the subject.', { purpose: ['reveal', 'object'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['product', 'weapon', 'building'], lab: 'world', recipe: `M.arcPush({ target: W.hero, dist: 15, az: 30, mm: 50, dur: 6 })` });
S('REV', 'Through-the-screen reveal', 'Push into a screen and out into the world it shows: the data becomes real.', { purpose: ['reveal', 'transition'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['monitor', 'phone', 'billboard'], lab: 'world', recipe: `M.pushThrough({ through: W.screen.point, normal: W.screen.normal, before: 9, after: 2, mm: 35, mm1: 24, dur: 5 })` });
S('REV', 'Climb and tilt reveal', 'Pedestal up while the aim lifts from ground to horizon: the scope of the problem.', { purpose: ['reveal', 'place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['field', 'yard', 'harbour'], lab: 'world', recipe: `M.craneReveal({ target: W.office, dist: 70, az: -20, rise: 18, mm: 28, dur: 7 })` });
S('REV', 'Slow push to the door', 'Approach the threshold while VO withholds: what is inside?', { purpose: ['reveal', 'tension'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['door', 'vault', 'container doors'], lab: 'world', recipe: `M.dollyIn({ target: M.vec.add(W.hero, [5, 0, 1.8]), dist: 12, az: 70, el: 2, push: 0.45, mm: 40, dur: 7, ease: 'gentle' })` });
S('REV', 'Top-down push to the pattern', 'From above, closing on a detail inside a pattern: the one that is different.', { purpose: ['reveal', 'number'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['parking lot', 'graves', 'containers', 'crowd'], lab: 'world', recipe: `M.topDownPush({ target: W.hero, h0: 110, h1: 14, yaw: 20, mm: 35, dur: 7 })` });
S('REV', 'Dutch drift into unease', 'The horizon tips slowly as the VO turns: something is wrong here.', { purpose: ['reveal', 'tension'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['corridor', 'office', 'street'], lab: 'world', recipe: `M.dutchDrift({ target: W.office, dist: 40, az: -10, el: 6, roll: 8, push: 0.12, mm: 35, dur: 7 })` });
S('REV', 'Rise behind the figure', 'Over-the-shoulder rise: we see what the person sees, and it is big.', { purpose: ['reveal', 'person'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['figure at edge', 'operator at desk'], lab: 'world', t0: 9, recipe: `M.lookAt(M.layer(M.hold({ pos: M.vec.add(W.figureAt(9), [-2.6, 1.7, 1.5]), look: W.tower, mm: 28 }, 7), M.pedestal({ target: [0, 0, 0], dist: 1, rise: 9, dur: 7 })), W.tower, { lead: 0 })` });
S('REV', 'God\'s-eye drop to the subject', 'From pure pattern to one subject: the abstraction becomes a person or a thing.', { purpose: ['reveal'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['crowd', 'city grid', 'battlefield'], lab: 'world', t0: 4, recipe: `M.godRotate({ target: W.figureAt(8), h0: 140, h1: 9, spin: 35, mm: 35, dur: 8, ease: 'settle' })` });
S('REV', 'Spin-out from the object', 'Leave the object with a rising orbit until its surroundings make sense of it.', { purpose: ['reveal', 'ending'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['object on table', 'car', 'body'], lab: 'world', recipe: `M.helixRise({ target: W.object, r0: 1.2, r1: 16, h0: 0.4, h1: 18, arc: 170, mm: 28, dur: 8 })` });

// ============================================================================ FOLLOW / TRACKING
S('FOL', 'Chase cam behind the car', 'Momentum, pursuit, destination unknown. The car leads the story.', { purpose: ['person', 'time'], scale: 'medium', energy: 'high', cost: 'T2', sets: ['car', 'truck', 'boat'], lab: 'world', t0: 2, recipe: `M.followChase({ subject: W.car, dur: 7 })` });
S('FOL', 'Side tracking at speed', 'Parallel track in profile: urgency with geography sliding behind.', { purpose: ['person', 'time'], scale: 'medium', energy: 'high', cost: 'T2', sets: ['car', 'runner', 'train'], lab: 'world', t0: 3, recipe: `M.followSide({ subject: W.car, offset: [-9, 1.3, 0], mm: 50, dur: 6 })` });
S('FOL', 'Lead shot, backing away', 'The camera retreats in front of the subject: it is coming toward us, determined.', { purpose: ['person', 'tension'], scale: 'medium', energy: 'high', cost: 'T2', sets: ['car', 'walker', 'convoy'], lab: 'world', t0: 4, recipe: `M.followLead({ subject: W.car, offset: [0.6, 1.5, -13], mm: 40, dur: 6 })` });
S('FOL', 'Overhead tracking', 'God\'s-eye follow: the route and the maze; the subject as a dot in a system.', { purpose: ['mechanism', 'place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['car', 'convoy', 'ship'], lab: 'world', t0: 6, recipe: `M.followTop({ subject: W.car, offset: [0, 45, 0.001], mm: 35, dur: 8 })` });
S('FOL', 'Fincher locked follow', 'The frame is glued to the walker: no float, no lag, exact. The audience is surveilling.', { purpose: ['person', 'tension'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['walker', 'operator', 'suspect'], lab: 'world', t0: 2, recipe: `M.follow({ subject: W.figure, offset: [1.2, 1.55, 3.6], lag: 0.08, lookahead: 0.1, lookHeight: 1.45, mm: 40, dur: 7 })` });
S('FOL', 'Operator follow with breath', 'A human operator behind the walker: present, slightly late, alive.', { purpose: ['person', 'memory'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['walker', 'crowd'], lab: 'world', t0: 3, recipe: `M.follow({ subject: W.figure, offset: [0.5, 1.6, 4.2], lag: 0.45, lookahead: 0.3, lookHeight: 1.3, mm: 35, float: 0.03, dur: 7 })` });
S('FOL', 'Profile walk, long lens', 'Long-lens side track of a walker: compressed background, introspection.', { purpose: ['person', 'memory'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['walker', 'commuter'], lab: 'world', t0: 2, recipe: `M.follow({ subject: W.figure, offset: [-9, 1.4, 0], lag: 0.2, lookahead: 0.2, lookHeight: 1.1, mm: 85, dur: 7 })` });
S('FOL', 'Track-in on the walker\'s back', 'Close behind, gaining: we are about to learn where they are going.', { purpose: ['person', 'tension'], scale: 'close', energy: 'mid', cost: 'T2', sets: ['walker', 'guard'], lab: 'world', t0: 2, recipe: `M.blend(M.follow({ subject: W.figure, offset: [0.3, 1.6, 5.5], lag: 0.3, lookHeight: 1.4, mm: 40, dur: 7 }), M.follow({ subject: W.figure, offset: [0.25, 1.62, 1.8], lag: 0.3, lookHeight: 1.45, mm: 40, dur: 7 }), [0.5, 6.5])` });
S('FOL', 'Car arrives at destination', 'Follow the car as it brakes and settle into a hold as it stops: arrival.', { purpose: ['place', 'time'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['car', 'ship docking', 'plane landing'], lab: 'world', t0: 15, recipe: `M.followChase({ subject: W.car, offset: [-2.5, 2.2, 9], lookahead: 0.6, dur: 8 })` });
S('FOL', 'Orbiting follow', 'Circle the moving subject while travelling with it: dynamic hero beat.', { purpose: ['person'], scale: 'medium', energy: 'high', cost: 'T2', sets: ['car', 'boat', 'runner'], lab: 'world', t0: 3, recipe: `M.orbit({ target: W.car, dist: 11, az: -60, arc: 120, el: 8, mm: 35, dur: 7 })` });
S('FOL', 'Drone follow and rise', 'Follow the car, then climb away from it: the journey becomes geography.', { purpose: ['place', 'time'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['car', 'convoy', 'hiker'], lab: 'world', t0: 4, recipe: `M.layer(M.followChase({ subject: W.car, offset: [0, 4, 12], dur: 8 }), M.pedestal({ target: [0, 0, 0], dist: 1, rise: 30, dur: 8, ease: 'in' }))` });
S('FOL', 'FPV chase through the streets', 'Low, banked and fast through the gaps: adrenaline, speed, reckless pursuit.', { purpose: ['tension', 'time'], scale: 'medium', energy: 'high', cost: 'T2', sets: ['streets', 'canyon', 'forest'], lab: 'world', recipe: `M.fpvWeave({ points: W.weave, mm: 16, dur: 10 })` });
S('FOL', 'Track along the road', 'The road itself is the subject: a route, a supply line, a migration.', { purpose: ['mechanism', 'place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['road', 'pipeline', 'border wall', 'river'], lab: 'world', recipe: `M.trackPath({ points: W.road.slice(1, 6).map(p => M.vec.add(p, [0, 16, 18])), lookY: -10, mm: 28, dur: 10 })` });
S('FOL', 'Wheel-level tracking', 'Low on the ground beside the wheel: weight, machinery, power.', { purpose: ['object', 'tension'], scale: 'close', energy: 'high', cost: 'T2', sets: ['car', 'train', 'tank'], lab: 'world', t0: 3, recipe: `M.follow({ subject: W.car, offset: [2.2, -0.35, 1.2], lag: 0.05, lookahead: 0.15, lookHeight: -0.3, mm: 24, dur: 5 })` });
S('FOL', 'Lead-room pan', 'A fixed camera pans with the subject passing; leaves space ahead of it.', { purpose: ['person', 'place'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['car passing', 'walker passing'], lab: 'world', t0: 3, recipe: `M.lookAt(M.lockOff({ target: W.carAt(6), dist: 22, az: 160, el: 3, mm: 40, dur: 6 }), W.car, { lead: 0.6, height: -0.2 })` });
S('FOL', 'Converging follow', 'Two subjects about to meet; the camera tracks one and finds the other.', { purpose: ['tension', 'person'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['car + walker', 'two ships'], lab: 'world', t0: 2, recipe: `M.lookAt(M.follow({ subject: W.figure, offset: [-1.5, 1.7, 5], lag: 0.3, lookHeight: 1.3, mm: 32, dur: 7 }), W.car, { lead: 0.3, weight: [3, 5.5] })` });
S('FOL', 'Top-down chase into turn', 'Overhead, rotating with the car into a bend: precision, planning, a heist.', { purpose: ['mechanism', 'tension'], scale: 'wide', energy: 'high', cost: 'T2', sets: ['car', 'convoy'], lab: 'world', t0: 10, recipe: `M.followTop({ subject: W.car, offset: [0, 26, 0.001], lag: 0.2, mm: 28, dur: 7 })` });
S('FOL', 'Slow-motion beat in the chase', 'Speed-ramp a follow: the world slows at the decisive moment, then snaps back.', { purpose: ['tension', 'reveal'], scale: 'medium', energy: 'high', cost: 'T2', sets: ['car', 'runner', 'falling object'], lab: 'world', t0: 2, recipe: `M.speedRamp(M.followChase({ subject: W.car, offset: [1.5, 1.4, 6], dur: 8 }), [[0, 1], [0.35, 1], [0.5, 0.2], [0.65, 0.2], [0.8, 1], [1, 1]])`, note: 'Apply move.warp(t) to the world clock too, so the subject slows with the camera.' });
S('FOL', 'Pedestrian POV drift', 'Eye height, walking pace, a little breath: the viewer is the walker.', { purpose: ['memory', 'place'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['street', 'corridor', 'market'], lab: 'world', t0: 2, recipe: `M.follow({ subject: W.figure, offset: [0, 1.65, 0.1], lag: 0.4, lookahead: 1.4, lookHeight: 1.55, mm: 28, float: 0.035, dur: 7 })` });
S('FOL', 'Track and let go', 'Follow the subject, then stop and let it leave frame: abandonment, departure.', { purpose: ['ending', 'person'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['car leaving', 'walker leaving'], lab: 'world', t0: 4, recipe: `M.seq([M.followSide({ subject: W.car, offset: [-8, 1.3, 0], dur: 4 }), (prev) => M.lookAt(M.hold(prev, 4), W.car, { lead: 0.2, weight: 0.35, height: -0.3 })], { overlap: 1.2 })` });
S('FOL', 'Crane-down onto the arrival', 'Fall from height to meet the car as it stops: the arrival lands.', { purpose: ['place', 'reveal'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['car arrival', 'ship', 'convoy'], lab: 'world', t0: 15, recipe: `M.craneDown({ target: W.carAt(21), dist: 14, az: -120, el: 4, rise: 22, mm: 28, dur: 7 })` });
S('FOL', 'Dolly with the walker\'s gaze', 'Tracking beside a figure while the aim drifts toward what they look at.', { purpose: ['person', 'reveal'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['walker', 'guard', 'tourist'], lab: 'world', t0: 2, recipe: `M.lookAt(M.follow({ subject: W.figure, offset: [2.5, 1.5, 0.5], lag: 0.25, lookHeight: 1.4, mm: 35, dur: 7 }), W.tower, { lead: 0, weight: [2.5, 6] })` });
S('FOL', 'High chase, long lens', 'Long-lens aerial on the car: surveillance footage, being watched.', { purpose: ['tension', 'mechanism'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['car', 'convoy', 'boat'], lab: 'world', t0: 5, recipe: `M.follow({ subject: W.car, offset: [-35, 40, 45], frame: 'local', lag: 0.5, lookahead: 0.4, lookHeight: 0, mm: 135, dur: 7 })` });
S('FOL', 'Spiral follow down to the car', 'Descend around the moving car: the target is acquired.', { purpose: ['tension', 'reveal'], scale: 'wide', energy: 'high', cost: 'T2', sets: ['car', 'ship', 'suspect'], lab: 'world', t0: 3, recipe: `M.spiralDescent({ target: W.car, h0: 70, h1: 3.5, r0: 50, r1: 12, arc: 200, mm: 28, dur: 8 })` });

// ============================================================================ ONER / BRIDGE
S('ONE', 'Sky-to-car', 'From the clouds down to a car on a road, then ride with it: the story finds its subject.', { purpose: ['place', 'person', 'transition'], scale: 'wide', energy: 'mid', cost: 'T3', sets: ['car', 'convoy', 'runner'], lab: 'world', t0: 0, recipe: `M.seq([M.descendFromSky({ ground: W.carAt(4.5), h0: 900, h1: 22, heading: [1, 0, 0], ease: 'in', dur: 5 }), M.followChase({ subject: W.car, offset: [0, 3, 10], dur: 7 })], { overlap: 1.6 })` });
S('ONE', 'Car-to-destination', 'Ride with the car, rise and push ahead to show where it is going, land as it stops.', { purpose: ['place', 'time', 'transition'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['car', 'ship', 'train'], lab: 'world', t0: 11, recipe: `M.seq([M.followChase({ subject: W.car, dur: 5 }), M.craneUp({ target: W.carAt(21), dist: 26, az: -150, el: 10, rise: 12, dur: 6, ease: 'out' })], { overlap: 1.5 })` });
S('ONE', 'Street-to-map', 'From street level up into a top-down map: the event becomes a pattern.', { purpose: ['place', 'number', 'transition'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['street', 'city map'], lab: 'world', recipe: `M.seq([M.craneUp({ target: W.hero, dist: 14, az: 20, el: 4, rise: 10, dur: 4, ease: 'in' }), M.pullBackToPlanet({ ground: W.plaza, h0: 30, h1: 2500, heading: [0, 0, -1], dur: 6, ease: 'out' })], { overlap: 1.5 })` });
S('ONE', 'Map-to-globe', 'Keep pulling out until the map curves into a planet: local becomes global.', { purpose: ['place', 'number', 'transition'], scale: 'wide', energy: 'mid', cost: 'T3', sets: ['map', 'globe'], lab: 'world', recipe: `M.pullBackToPlanet({ ground: W.plaza, center: W.planet.center, radius: W.planet.radius, h0: 1500, h1: 420000, heading: [0, 0, -1], spin: 20, mm: 35, dur: 9 })` });
S('ONE', 'Globe-to-orbit', 'From a globe to a satellite\'s view: the watcher\'s perspective.', { purpose: ['place', 'tension'], scale: 'wide', energy: 'low', cost: 'T1', sets: ['globe', 'satellite'], lab: 'globe', recipe: `M.seq([M.globeFly({ center: W.globe.center, radius: W.globe.radius, from: { lat: 51.5, lon: 0, alt: 6 }, to: { lat: 40.7, lon: -74, alt: 8 }, ease: 'in', dur: 6 }), (p) => M.dollyOut({ target: W.globe.center, dist: M.vec.len(p.pos), az: -60, el: 30, pull: 2.4, mm: 35, dur: 5, ease: 'out' })], { overlap: 1.5 })` });
S('ONE', 'Screen-push-into-world', 'Push into a screen; the pixels become the place. Data to reality.', { purpose: ['transition', 'reveal'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['monitor', 'phone', 'control room'], lab: 'world', recipe: `M.seq([M.pushThrough({ through: W.screen.point, normal: W.screen.normal, before: 7, after: 0.5, mm: 35, dur: 4, ease: 'in' }), M.flyThrough({ gap: [-13, 4, -60], dir: [0, 0, -1], before: 52, after: 60, rise: 4, mm: 24, dur: 6, ease: 'out' })], { overlap: 1.2 })`, note: 'In an episode, cut to the destination set at the frame the lens fills with the screen (luminance match).' });
S('ONE', 'Eye-to-world', 'Push into a face until the eye fills frame, emerge in what it sees: memory, obsession.', { purpose: ['memory', 'transition'], scale: 'close', energy: 'mid', cost: 'T2', sets: ['figure', 'portrait photo'], lab: 'world', t0: 9, recipe: `M.seq([M.dollyIn({ target: W.figureHead(9), dist: 3.4, az: 90, el: 0, push: 0.92, mm: 50, dur: 4, ease: 'in' }), M.pullBackReveal({ target: W.tower, dist: 30, az: 100, pull: 3, rise: 10, mm: 35, dur: 6, ease: 'out' })], { overlap: 1.0 })`, note: 'Cut or flash on the darkest frame inside the eye; the seq keeps the speed continuous across it.' });
S('ONE', 'Document-zoom-into-scene', 'Close on a page, push into a line of it, and arrive in the scene it describes.', { purpose: ['object', 'transition', 'memory'], scale: 'close', energy: 'mid', cost: 'T2', sets: ['document', 'photo', 'letter', 'map print'], lab: 'world', recipe: `M.cut([M.topDownPush({ target: W.doc.center, h0: 1.4, h1: 0.1, yaw: 0, mm: 50, dur: 4, ease: 'in' }), M.descendFromSky({ ground: W.hero, h0: 140, h1: 12, heading: [0, 0, -1], lookEnd: W.hero, dur: 6, ease: 'out' })])`, note: 'A hidden cut inside the white of the page (M.cut): both halves move straight down at full speed across the join. Dissolve the page plate over the first 0.3 s of the scene.' });
S('ONE', 'Planet-to-plaza', 'Powers of Ten inward: orbit to the one place that matters, landing at eye level.', { purpose: ['place', 'chapter'], scale: 'wide', energy: 'mid', cost: 'T3', sets: ['globe+city'], lab: 'world', recipe: `M.seq([M.descendFromSky({ ground: W.plaza, center: W.planet.center, radius: W.planet.radius, h0: 400000, h1: 60, heading: [0, 0, -1], dur: 9, ease: 'in' }), M.overheadToEye({ target: W.hero, dist: 24, az: 0, h0: 50, eye: 1.8, dur: 6, ease: 'out' })], { overlap: 2 })` });
S('ONE', 'Street-to-orbit', 'One continuous pull from a person on the street to the planet: one life in the system.', { purpose: ['ending', 'place'], scale: 'wide', energy: 'low', cost: 'T3', sets: ['figure + globe'], lab: 'world', t0: 9, recipe: `M.seq([M.dollyOut({ target: M.vec.add(W.figureAt(9), [0, 1.2, 0]), dist: 4, az: 50, el: 16, pull: 3, dur: 4, ease: 'in' }), M.pullBackToPlanet({ ground: W.figureAt(9), center: W.planet.center, radius: W.planet.radius, h0: 20, h1: 420000, heading: [0, 0, -1], dur: 9, ease: 'out' })], { overlap: 1.5 })` });
S('ONE', 'Window-to-desk', 'From the street into the lit window and down onto the desk inside: the private decision.', { purpose: ['reveal', 'object', 'transition'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['office', 'apartment', 'study'], lab: 'world', recipe: `M.seq([M.pushThrough({ through: W.window.point, normal: W.window.normal, before: 24, after: 2, target: W.window.inside, mm: 32, dur: 5, ease: 'in' }), M.dollyIn({ target: W.window.inside, dist: 4.2, az: 10, el: 28, push: 0.35, mm: 40, dur: 4, ease: 'out' })], { overlap: 1.2 })` });
S('ONE', 'Hero-to-skyline', 'From the object to the city that made it: the evidence and its context, unbroken.', { purpose: ['object', 'place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['object + city'], lab: 'world', recipe: `M.seq([M.orbit({ target: W.hero, dist: 12, az: 10, arc: 40, el: 6, dur: 4, ease: 'in' }), M.helixRise({ target: W.hero, r0: 13, r1: 70, h0: 3, h1: 60, az: 50, arc: 90, lookY: 25, dur: 7, ease: 'out' })], { overlap: 1.5 })` });
S('ONE', 'Car-to-map', 'Ride with the car, then climb vertically until its route is a line on a map.', { purpose: ['mechanism', 'number', 'transition'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['car route', 'supply chain', 'migration'], lab: 'world', t0: 3, recipe: `M.seq([M.followTop({ subject: W.car, offset: [0, 20, 0.001], dur: 4 }), M.pullBackToPlanet({ ground: W.carAt(7.5), h0: 20, h1: 1800, heading: [1, 0, 0], dur: 6, ease: 'out' })], { overlap: 1.5 })` });
S('ONE', 'Tower climb to rooftop view', 'Rise up the facade and over the roof edge to the view beyond: ascent, power.', { purpose: ['place', 'reveal'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['tower', 'cliff', 'ship side'], lab: 'world', recipe: `M.seq([M.pedestal({ target: M.vec.add(W.tower, [0, -28, 7]), dist: 14, az: 0, rise: 56, ease: 'in', dur: 6 }), (p) => M.trackPath({ points: [p.pos, M.vec.add(W.towerTop, [0, 10, -2]), M.vec.add(W.towerTop, [0, 16, -40])], target: [-120, 0, -200], ease: 'out', dur: 6 })], { overlap: 1.2 })` });
S('ONE', 'Map-to-street drop', 'Start on a map, fall into it and land in the street: the abstraction becomes real.', { purpose: ['place', 'transition'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['map + street'], lab: 'world', recipe: `M.seq([M.mapFlyTo({ from: { at: [-600, 400], width: 3000 }, to: { at: [W.plaza[0], W.plaza[2]], width: 260 }, ease: 'in', dur: 6 }), M.overheadToEye({ target: W.hero, dist: 26, az: 0, h0: 55, eye: 2, ease: 'out', dur: 6 })], { overlap: 1.8 })` });
S('ONE', 'Figure-to-car hand-off', 'Follow the walker until the car passes, then hand the camera to the car.', { purpose: ['person', 'transition'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['two subjects crossing'], lab: 'world', t0: 2, recipe: `M.seq([M.follow({ subject: W.figure, offset: [1, 1.6, 4], lag: 0.3, lookHeight: 1.3, dur: 4 }), M.followSide({ subject: W.car, offset: [-7, 1.6, 1], dur: 6 })], { overlap: 1.8 })` });
S('ONE', 'Dive from the roof', 'FPV off a rooftop edge, down the facade and out across the street.', { purpose: ['tension', 'transition'], scale: 'wide', energy: 'high', cost: 'T2', sets: ['tower', 'cliff', 'dam'], lab: 'world', recipe: `M.fpvDive({ edge: W.towerTop, dir: [0, 0, 1], height: 72, mm: 16, dur: 7 })` });
S('ONE', 'Globe-to-city', 'Fly to the place on the globe, keep descending through the haze into the street.', { purpose: ['place', 'chapter'], scale: 'wide', energy: 'mid', cost: 'T3', sets: ['globe + city'], lab: 'world', recipe: `M.seq([M.descendFromSky({ ground: W.plaza, center: W.planet.center, radius: W.planet.radius, h0: 300000, h1: 400, heading: [0, 0, -1], ease: 'in', dur: 8 }), M.descendFromSky({ ground: W.hero, h0: 400, h1: 18, lookEnd: W.tower, landAt: 0.5, heading: [0, 0, -1], ease: 'out', dur: 6 })], { overlap: 2 })` });
S('ONE', 'Room-to-street exit', 'From the desk, back out through the window and down into the street: the decision leaves the room.', { purpose: ['transition', 'place'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['office', 'apartment'], lab: 'world', recipe: `M.reverse(M.seq([M.pushThrough({ through: W.window.point, normal: W.window.normal, before: 24, after: 2, target: W.window.inside, mm: 32, dur: 5, ease: 'in' }), M.dollyIn({ target: W.window.inside, dist: 4.2, az: 10, el: 28, push: 0.35, mm: 40, dur: 4, ease: 'out' })], { overlap: 1.2 }))` });
S('ONE', 'Flyover to the next set', 'Skim over a subject and keep flying to the next location: geographic bridge.', { purpose: ['transition', 'place'], scale: 'wide', energy: 'high', cost: 'T2', sets: ['two locations in one city'], lab: 'world', recipe: `M.seq([M.flyover({ target: W.hero, dir: [1, 0, -0.5], h0: 4, h1: 18, reach: 30, ease: 'in', dur: 5 }), M.arcPush({ target: W.office, dist: 44, az: -20, ease: 'out', dur: 6 })], { overlap: 1.6 })` });
S('ONE', 'Ridge-to-car', 'Rise over the ridge, find the car on the road, and settle on it.', { purpose: ['place', 'person'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['landscape + vehicle'], lab: 'world', t0: 1, recipe: `M.seq([M.droneRidgeReveal({ crest: W.ridge.crest, dir: W.ridge.dir, vista: W.plaza, back: 25, clear: 8, ahead: 30, ease: 'in', dur: 6 }), M.followChase({ subject: W.car, offset: [0, 18, 26], lookahead: 0.5, dur: 6 })], { overlap: 2 })` });
S('ONE', 'Hero-to-detail macro', 'From the whole object down onto one detail without a cut: the clue in context.', { purpose: ['object', 'reveal'], scale: 'close', energy: 'low', cost: 'T2', sets: ['object', 'document', 'device'], lab: 'world', recipe: `M.seq([M.arcPush({ target: W.object, dist: 3, az: -10, mm: 50, ease: 'in', dur: 4 }), M.macroSlide({ target: M.vec.add(W.object, [0, 0.05, 0]), dist: 0.55, az: 20, el: 40, mm: 85, ease: 'out', dur: 5 })], { overlap: 1.2 })` });
S('ONE', 'Orbit-to-follow', 'Circle a waiting subject; as it moves off, the orbit becomes a follow.', { purpose: ['person', 'transition'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['car pulling away', 'walker starting'], lab: 'world', t0: 1, recipe: `M.seq([M.orbit({ target: W.car, dist: 9, az: 60, arc: 70, el: 6, ease: 'in', dur: 4 }), M.followChase({ subject: W.car, offset: [2, 1.8, 8], dur: 5 })], { overlap: 1.6 })` });
S('ONE', 'Plaza-to-tower-top', 'From ground level beside the hero to the tower top: the chain of command.', { purpose: ['mechanism', 'place'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['street + HQ'], lab: 'world', recipe: `M.seq([M.heroRise({ target: W.plaza, height: 2.6, az: 220, dur: 4, ease: 'in' }), (p) => M.trackPath({ points: [p.pos, [-18, 30, -6], M.vec.add(W.towerTop, [6, 14, 18])], target: W.towerTop, ease: 'out', dur: 7 })], { overlap: 1.3 })` });
S('ONE', 'Satellite-to-target', 'Satellite view locks on, then falls straight down on the target: surveillance becomes action.', { purpose: ['tension', 'reveal'], scale: 'wide', energy: 'high', cost: 'T3', sets: ['satellite + site'], lab: 'world', t0: 3, recipe: `M.seq([M.descendFromSky({ ground: W.carAt(8), center: W.planet.center, radius: W.planet.radius, h0: 200000, h1: 200, heading: [1, 0, 0], ease: 'in', dur: 7 }), M.followTop({ subject: W.car, offset: [0, 30, 0.001], dur: 5 })], { overlap: 2 })` });
S('ONE', 'Speed-ramped oner', 'A long continuous move with a slow-motion beat in the middle: the moment of impact.', { purpose: ['tension', 'reveal'], scale: 'medium', energy: 'high', cost: 'T2', sets: ['street', 'chase', 'explosion'], lab: 'world', t0: 2, recipe: `M.speedRamp(M.seq([M.followSide({ subject: W.car, offset: [-8, 1.5, 0], dur: 4 }), M.orbit({ target: W.carAt(8), dist: 12, az: -90, arc: 90, el: 6, dur: 5, ease: 'out' })], { overlap: 1.4 }), [[0, 1], [0.35, 1], [0.5, 0.25], [0.7, 0.25], [0.85, 1], [1, 1]])` });
S('ONE', 'Descend-and-follow-the-walker', 'From above the city down onto one person and walk with them: from statistics to a life.', { purpose: ['person', 'number', 'transition'], scale: 'wide', energy: 'mid', cost: 'T2', sets: ['crowd', 'city + figure'], lab: 'world', t0: 9, recipe: `M.seq([M.descendFromSky({ ground: W.figureAt(9), h0: 260, h1: 8, heading: [1, 0, 0], ease: 'in', dur: 6 }), M.follow({ subject: W.figure, offset: [-1, 1.8, 4.5], lag: 0.4, lookHeight: 1.2, dur: 6 })], { overlap: 2 })` });
S('ONE', 'Globe hop', 'Fly from one city to another across the globe: connection, distance, a network.', { purpose: ['number', 'place', 'mechanism'], scale: 'wide', energy: 'mid', cost: 'T1', sets: ['globe', 'map'], lab: 'globe', recipe: `M.globeFly({ center: W.globe.center, radius: W.globe.radius, from: { lat: 40.7, lon: -74, alt: 7 }, to: { lat: 51.5, lon: 0, alt: 6 }, tilt: 25, mm: 35, dur: 8 })` });

// ============================================================================ CHARACTER / SILHOUETTE
S('CHR', 'Silhouette against the sky', 'A lone dark figure against the lit sky: the stoic operator, calm inside chaos.', { purpose: ['person'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['figure', 'ridge', 'rooftop'], lab: 'world', t0: 9, recipe: `M.lockOff({ target: M.vec.add(W.figureAt(9), [0, 1.5, 0]), dist: 9, az: 180, el: -8, mm: 50, dur: 6 })` });
S('CHR', 'Low-angle hero rise', 'Rising from the ground to a low angle on the figure: resolve, power, the turn.', { purpose: ['person', 'reveal'], scale: 'medium', energy: 'mid', cost: 'T2', sets: ['figure', 'statue'], lab: 'world', t0: 9, recipe: `M.heroRise({ target: W.figureAt(9), az: 75, mm: 24, dur: 6 })` });
S('CHR', 'Slow push on the back', 'Behind the figure, creeping in while they look out: decision, interior thought.', { purpose: ['person', 'tension'], scale: 'medium', energy: 'low', cost: 'T2', sets: ['figure at window', 'figure at edge'], lab: 'world', t0: 9, recipe: `M.creep({ target: M.vec.add(W.figureAt(9), [0, 1.4, 0]), dist: 5, az: -100, el: 2, push: 0.18, mm: 50, dur: 8 })` });
