// ---------------------------------------------------------------------------- build
const counts = {}; const shots = [];
for (const e of list) {
  counts[e.cat] = (counts[e.cat] ?? 0) + 1;
  const id = `${e.cat}-${String(counts[e.cat]).padStart(3, '0')}`;
  let m; try { m = new Function('M', 'W', `return (${e.recipe});`)(M, W); } catch (err) { throw new Error(`${id} ${e.name}: ${err.message}`); }
  if (!M.isMove(m)) throw new Error(`${id} ${e.name}: recipe did not return a Move`);
  let lo = Infinity, hi = 0; for (let i = 0; i <= 40; i++) { const mm = m.at(m.dur * i / 40).mm; lo = Math.min(lo, mm); hi = Math.max(hi, mm); }
  const lens = Math.round(lo) === Math.round(hi) ? `${Math.round(lo)}mm` : `${Math.round(m.at(0).mm)}→${Math.round(m.at(m.dur).mm)}mm`;
  const d = +m.dur.toFixed(1), range = [+(d * 0.8).toFixed(1), +(d * 1.3).toFixed(1)];
  shots.push({ id, category: e.cat, name: e.name, use: e.use, purpose: e.purpose, scale: e.scale, energy: e.energy, recipe: e.recipe, lens, duration: range, dur: d, cost: e.cost, sets: e.sets, lab: e.lab ?? 'world', t0: e.t0 ?? 0, ...(e.note ? { note: e.note } : {}) });
}
const catalog = {
  version: 1,
  generated: 'node docs/shots/build-catalog.mjs',
  about: 'Named camera moves for engine/camera.js. recipe is a JS expression in scope { M: camera.js module, W: world handles } returning a Move; duration is the usable range (stretch with M.retime). See docs/shots/catalog.md.',
  handles: 'W.hero W.object W.doc W.tower W.towerTop W.towerBox W.office W.window W.screen W.gap W.ridge W.weave W.road W.plaza W.planet W.globe W.car W.carAt(t) W.figure W.figureAt(t) W.figureHead(t) (projects/shot-lab/world-handles.mjs)',
  cost: { T1: '<= 300 ms/frame at 1080p llvmpipe', T2: '300-450 ms/frame', T3: '> 450 ms/frame: budget against T1 neighbours' },
  categories: Object.fromEntries(Object.entries(CATS).map(([k, [n, d]]) => [k, { name: n, about: d, count: counts[k] ?? 0 }])),
  shots,
};
fs.writeFileSync(path.join(here, 'catalog.json'), JSON.stringify(catalog, null, 1));

// markdown
const md = [];
md.push('# Shot catalog: 200 named camera moves', '');
md.push('Generated by `node docs/shots/build-catalog.mjs` from the same entries as `catalog.json` (machine-readable, used by the `shot-design` skill). Every recipe is a real `engine/camera.js` expression, evaluated against the shot-lab handles and smoothness-tested (`node projects/shot-lab/test-camera.mjs --catalog`). Emotional grammar and sources: `docs/shots/camera-language.md`.', '');
md.push('**How to use a recipe.** `W` is the episode\'s handle object (same names as `projects/shot-lab/world-handles.mjs`: `W.hero`, `W.car`, `W.figure`, ...). Build the move once per set, then in `update(t)`: `M.apply(camera, move.at(t), { fx })`. Stretch to the shot with `M.retime(move, shot.duration)`. Chain with `M.seq([...])` for oners.', '');
md.push('**Fields.** *Use*: the emotion or job. *Purpose*: beat jobs for shot-design. *Scale / energy*: for the alternation rule. *Lens*: focal length (full-frame mm). *Dur*: usable range in seconds. *Cost*: T1 <= 300 ms/frame, T2 300-450, T3 > 450 (1080p, llvmpipe). *Sets*: scenes it suits.', '');
const total = shots.length;
md.push(`| Category | Count |`, `|---|---|`, ...Object.entries(CATS).map(([k, [n]]) => `| ${k} ${n} | ${counts[k]} |`), `| **Total** | **${total}** |`, '');
for (const [k, [n, about]] of Object.entries(CATS)) {
  md.push(`## ${k}: ${n}`, '', about, '');
  for (const s of shots.filter(x => x.category === k)) {
    md.push(`### ${s.id} ${s.name}`, '');
    md.push(`*${s.use}*`, '');
    md.push(`Purpose: ${s.purpose.join(', ')} · Scale: ${s.scale} · Energy: ${s.energy} · Lens: ${s.lens} · Dur: ${s.duration[0]}-${s.duration[1]} s · Cost: ${s.cost} · Sets: ${s.sets.join(', ')}`, '');
    md.push('```js', s.recipe, '```');
    if (s.note) md.push('', `Note: ${s.note}`);
    md.push('');
  }
}
fs.writeFileSync(path.join(here, 'catalog.md'), md.join('\n'));
console.log(`catalog: ${total} shots`, counts);
